import glob
import os
import shutil
from abc import ABCMeta, abstractmethod

from six import add_metaclass

from hran_pacman.bases.logger import LOGGER

PERMISSION_LEVEL = 511


@add_metaclass(ABCMeta)
class BaseStorage(object):
    """
    Base for every further storage implementation.
    """

    def __init__(self, path, baseline, package_name=""):
        super(BaseStorage, self).__init__()
        self.root_path = path
        self.baseline = baseline
        self.package_name = package_name if package_name else "{}.zip".format(baseline)
        self.package_path = os.path.join(self.container_path, self.package_name)

    @abstractmethod
    def create_storage(self):
        """Hook for ensuring that each package-specify container is created"""

    @property
    def container_path(self):
        """Path of created package container"""
        return self.root_path


@add_metaclass(ABCMeta)
class PermanentStorageBase(BaseStorage):
    """Base for permanent every permanent storage.

    Permanent storage is every non-temporary storage,
    doesn't matter if it was newly created or existed and was reused."""

    def __init__(self, path, baseline, package_name=""):
        super(PermanentStorageBase, self).__init__(path, baseline, package_name)

    def specific_package_available(self):
        return self._package_available()

    def _package_available(self):
        LOGGER.info("Checking if package exists at {}".format(self.package_path))
        return os.path.exists(self.package_path)

    def copy_content_from(self, other):
        """
        Clone package from another storage.

        :param other: other storage, must be child of BaseStorage

        """
        if self._is_storage(other):
            self.prepare_environment()
            self.copy_load(other)
            self.copy_sem(other)

    def copy_load(self, other):
        LOGGER.info("Copying load ({} -> {})".format(other.package_path, self.package_path))
        os.chmod(self.container_path, PERMISSION_LEVEL)
        shutil.copy(other.package_path, self.package_path)

    def copy_sem(self, other):
        sem_path = next(glob.iglob(os.path.join(other.container_path, "*BTSSiteEM*")), None)
        if sem_path is not None:
            target_path = os.path.join(self.container_path, os.path.basename(sem_path))
            LOGGER.info("Copying SEM ({} -> {})".format(sem_path, target_path))
            shutil.copy(sem_path, target_path)

    @abstractmethod
    def prepare_environment(self):
        """"""

    def _is_storage(self, other):
        return issubclass(other.__class__, BaseStorage)

    def create_storage(self):
        if not os.path.exists(self.container_path):
            LOGGER.info("Creating storage {}".format(self.container_path))
            os.mkdir(self.container_path)
            os.chmod(self.container_path, PERMISSION_LEVEL)
        else:
            LOGGER.info("Container directory {} exists,".format(self.container_path) + "supporting existing directory")
